import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"生产控制与前沿研究","description":"","frontmatter":{"translationSource":{"title":"生产控制与前沿研究","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}]]},"headers":[],"relativePath":"zh/production-control-and-frontier-research.md","filePath":"zh/page-0iirIEzxWlkfel2jMLIWJJ.md"}'),n={name:"zh/production-control-and-frontier-research.md"};function i(t,a,d,p,l,c){return o(),r("div",null,[...a[0]||(a[0]=[s('<div class="logistics-content"><h1 id="生产控制与前沿研究" tabindex="-1">生产控制与前沿研究 <a class="header-anchor" href="#生产控制与前沿研究" aria-label="Permalink to &quot;生产控制与前沿研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>0iirIEzxWlkfel2jMLIWJJ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5515548b0ac8f945.q90-2df7f7103be0fb88.webp" alt="生产控制与前沿研究"></p><p><span id="source-block-DWqjx1xibQYINqsd5UEFOm"></span></p><h2 id="阻塞生产原理-又名-爆仓动力学" tabindex="-1">阻塞生产原理（又名：爆仓动力学） <a class="header-anchor" href="#阻塞生产原理-又名-爆仓动力学" aria-label="Permalink to &quot;阻塞生产原理（又名：爆仓动力学）&quot;">​</a></h2><p>（咕咕咕，大部头施工中……要忙毕业开始缓更）</p><p><a href="https://www.skland.com/article?id=6331180" target="_blank" rel="noreferrer">jnk 的相关介绍文章</a></p><p><a href="/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices">讲解：自配平产线和自适应装置</a></p><p>撰写人：kokobird（1-4节）有问题请找我</p><details><summary>b站</summary><p>蓝海露花_kokobird，但我难得看b站，还不如在群里找我</p></details><p>最后更新：2026年9月13日</p><p>状态：1-2节基本内容已经按规划完成，但还会继续完善。3-4节缓慢施工中，同时可参考本人的相关（伪）论文pdf和视频。</p><p><span id="source-block-rCxnzFpo8mWaztoa5WoVYx"></span></p><h3 id="_1-引言" tabindex="-1">1 引言 <a class="header-anchor" href="#_1-引言" aria-label="Permalink to &quot;1 引言&quot;">​</a></h3><p><span class="mark-rose_red">欢迎来到智能生产小课堂，管理员。也许你刚刚按配方建设了简单的产线，对进阶内容跃跃欲试；又或许你已经能独立完成全地区基建的规划与布局，正在百无聊赖地四处冲浪。无论如何，希望本文能在闲暇时光带来或理论或实践的启发，领略到终末地工业独特的魅力所在。也许未来，你也能够建造出别具一格的产线，开创基建的新流派。</span></p><p><a href="/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 那我问你，什么是阻塞生产</a> · <a href="/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production">1.2 采用阻塞生产形式有什么好处</a> · <a href="/endfield-skydoc/zh/1-3-glossary">1.3 术语表（我自己也没法完全定义清楚，不看也罢）</a> · <a href="/endfield-skydoc/zh/1-4-prerequisite-basics">1.4 前置基础知识（待写）</a></p><p><span id="source-block-9lRjFmYbvOxK5tFFbqXsuJ"></span></p><h3 id="_2-阻塞生产的基本概念与简单例子" tabindex="-1">2 阻塞生产的基本概念与简单例子 <a class="header-anchor" href="#_2-阻塞生产的基本概念与简单例子" aria-label="Permalink to &quot;2 阻塞生产的基本概念与简单例子&quot;">​</a></h3><p>本节介绍阻塞生产的一些基本概念和简单例子。掌握理解本节内容，可以设计针对<span class="mark-rose_red"><strong>单种原料的多种成品</strong></span>的阻塞生产方案，达成大部分简单的智能生产需求。<strong>如果你认为已经掌握此部分内容，可以直接看完2.5节，能看懂就可以直接去第3节。</strong></p><p>值得在开篇处点明的是，在讨论阻塞生产时，往往存在<span class="mark-rose_red"><strong>理论规划</strong></span>与<span class="mark-rose_red"><strong>工程实现</strong></span>两个步骤。在<span class="mark-rose_red"><strong>理论规划</strong></span>阶段，我们讨论<u>需要生产什么成品，多少原料，需要什么生产环节，物料的流向与分配如何，优先级如何设计</u>等问题，例如我们分析需求发现需要把120蓝铁中X磨粉Y做蓝药，但这个阶段我们并不特别关心如何造一个X个蓝铁磨粉的产线。</p><p>而<span class="mark-rose_red"><strong>工程实现</strong></span>阶段，我们讨论<u>设备的布局，具体用什么结构实现优先级，如何优化结构</u>等问题。事实上，在<span class="mark-rose_red"><strong>理论规划</strong></span>充分的情况下，绝大部分时候工程实现只需要机械地按照方案进行连线即可，优化布线也不是本文所关注的重点（但是仍然很需要技术含量）。因此，后面大部分内容是侧重于<span class="mark-rose_red"><strong>理论规划</strong></span>的分析讨论，而<span class="mark-rose_red"><strong>工程实现</strong></span>中一些常用的工程结构则会放在附录中。</p><p><a href="/endfield-skydoc/zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road">2.1 Hello World：蓝铁矿的命途分叉</a> · <a href="/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking">2.2 花开两朵：切换型阻塞与平衡型阻塞</a> · <a href="/endfield-skydoc/zh/2-3-the-controlled-controlled-branch-and-the-unfree-free-branch">2.3 受控的受控端 &amp; 不自由的自由端 （考虑弃用）</a></p><p>说明：考虑抛弃受控端和自由端的叫法，换成阻塞端和流通端。因为只考虑分流时，外部限制控制受控端再控制自由端；但是考虑汇流时，方向是反过来的，所以不如还是叫阻塞端和流通端，再单独区分控制关系好了。后面的叫法暂时还没调整</p><p><a href="/endfield-skydoc/zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you">2.3 阻塞端与流通端：你控控我，我控控你</a> · <a href="/endfield-skydoc/zh/2-4-faster-than-light-upstream-propagation-of-blocking-signals">2.4 阻塞信号の“超光速”反向传播规律</a> · <a href="/endfield-skydoc/zh/2-5-is-a-stash-not-just-a-special-splitter">2.5 箱子不就是特殊的分流器吗？（核心内容⭐）</a> · <a href="/endfield-skydoc/zh/practical-exercise-a-coupled-xircon-yazhen-syringe-line-using-120">实战演练 120蓝铁的壤晶-蓝药耦合产线解析</a> · <a href="/endfield-skydoc/zh/2-6-empty-storage-full-storage-we-need-more-oversupply">2.6 空仓？满仓？我们需要更多的加压！</a> · <a href="/endfield-skydoc/zh/appendix-common-priority-structures">附录 常见的优先级结构设计</a></p><p><span id="source-block-x00nPzaklxsQ7IkqVngiau"></span></p><h3 id="_3-进阶阻塞生产" tabindex="-1">3 进阶阻塞生产 <a class="header-anchor" href="#_3-进阶阻塞生产" aria-label="Permalink to &quot;3 进阶阻塞生产&quot;">​</a></h3><details><summary>还有进阶？！</summary><p>恭喜你，伟大产线的建设者，当你来到这里时，你已经了解了阻塞生产的基本概念，也就是大概明白了它到底是一个什么玩意儿，以及要如何实现它。现在，更广阔的天地已经为你敞开大门，请稍作休息，然后自由翱翔，并享受无尽的可能性吧。</p></details><p>本节定位为更难的生产需求的阻塞生产方案分析，包括：<strong>多原料多成品的自适应配平生产方案，固气、液气转化机零浪费的阻塞生产方案</strong>等。掌握本节内容，能够了解如何将阻塞生产原理与随版本更新出现的新需求相结合，达成更复杂的生产需求，并深入理解阻塞生产的动力学规律。</p><details><summary>3-4节的大部分内容都会在论文中有更详细的阐述</summary><p><a href="/endfield-skydoc/logistics/src/assets/attachments/%E6%BA%A2%E6%B5%81%E4%BE%9B%E6%96%99%E7%B3%BB%E7%BB%9F%E7%9A%84%E5%8A%A8%E5%8A%9B%E5%AD%A6%E4%B8%8E%E7%A8%B3%E5%AE%9A%E6%80%A7v2.pdf-4f2e850e4820968c.pdf">附件：溢流供料系统的动力学与稳定性v2.pdf</a></p><blockquote><p>原件：溢流供料系统的动力学与稳定性v2.pdf；大小：2910720；objKey：<code>60e2194df39147af852543a7e54218e2</code>；本地状态：已下载。</p></blockquote><p>2026/9/9更新v3版本，内容更丰富，形式更严格，<s>看起来更累</s>。可以直接从第一部分开始看，前面是数学建模的严格抽象化过程。</p><p><a href="/endfield-skydoc/logistics/src/assets/attachments/%E6%BA%A2%E6%B5%81%E4%BE%9B%E6%96%99%E7%B3%BB%E7%BB%9F%E7%9A%84%E5%8A%A8%E5%8A%9B%E5%AD%A6%E4%B8%8E%E7%A8%B3%E5%AE%9A%E6%80%A7v3.pdf-42361709e96659db.pdf">附件：溢流供料系统的动力学与稳定性v3.pdf</a></p><blockquote><p>原件：溢流供料系统的动力学与稳定性v3.pdf；大小：4337949；objKey：<code>172aa5bd73d04fc390b7d009a19835e5</code>；本地状态：已下载。</p></blockquote></details><p><a href="/endfield-skydoc/zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about">3.0 配平，自适应，最大价值产出，叽里咕噜说什么呢</a> · <a href="/endfield-skydoc/zh/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 自动配平思想的萌芽：息壤与源石粉末的爱恨情仇</a> · <a href="/endfield-skydoc/zh/3-2-the-highest-mountain-heavy-xiranite-and-pyrrolite">3.2 最高的山山？！重息壤AND灼铜</a> · <a href="/endfield-skydoc/zh/3-3-you-you-xiranite-freeloading-pig">3.3 你……你这头白吃息壤的猪！</a></p><p><span id="source-block-V0u4t2MI93uTva23MwciTO"></span></p><h4 id="_3-4-中电池满仓切换低电池-赫铜满仓切换灼铜等" tabindex="-1">3.4 中电池满仓切换低电池，赫铜满仓切换灼铜等 <a class="header-anchor" href="#_3-4-中电池满仓切换低电池-赫铜满仓切换灼铜等" aria-label="Permalink to &quot;3.4 中电池满仓切换低电池，赫铜满仓切换灼铜等&quot;">​</a></h4><p><a href="https://www.bilibili.com/video/BV1Ecu66TEiv" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Ecu66TEiv</a></p><p><a href="https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7</a></p><p><span id="source-block-q8wRFhJsdttOEPgUXXKzWs"></span></p><h3 id="_4-阻塞生产中的若干动力学问题" tabindex="-1">4 阻塞生产中的若干动力学问题 <a class="header-anchor" href="#_4-阻塞生产中的若干动力学问题" aria-label="Permalink to &quot;4 阻塞生产中的若干动力学问题&quot;">​</a></h3><p>本节定位为阻塞生产的理论数值分析，提供一些应用于生产设计的结论的数学推导与证明。对于阻塞生产产线设计无需掌握此节内容，仅需了解结论即可。</p><p><a href="/endfield-skydoc/zh/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 从阻塞流理论基石上建起阻塞生产学的大厦（缓更）</a> · <a href="/endfield-skydoc/zh/4-1-modeling-blocking-based-production-dynamics-discrete-continuous-and">4.1 阻塞生产动力分析的建模：从离散模型，连续模型到机器动力系统模型</a></p><p><span id="source-block-3S8rTspXHBNgZC5nPm6zvV"></span></p><h4 id="_4-2-两种原料两种成品的稳定性条件与分流区间" tabindex="-1">4.2 两种原料两种成品的稳定性条件与分流区间 <a class="header-anchor" href="#_4-2-两种原料两种成品的稳定性条件与分流区间" aria-label="Permalink to &quot;4.2 两种原料两种成品的稳定性条件与分流区间&quot;">​</a></h4><p><span id="source-block-FlCfyo96lld68gvkvF5hkf"></span></p><h4 id="_4-3-中间原料的情形-分离芯" tabindex="-1">4.3 中间原料的情形（分离芯） <a class="header-anchor" href="#_4-3-中间原料的情形-分离芯" aria-label="Permalink to &quot;4.3 中间原料的情形（分离芯）&quot;">​</a></h4><p>目前存在中间原料的典型情况就是分离芯，如下图所示，生产灼铜需要分离芯+息壤（气）+赤铜块，生产重息壤需要分离芯+息壤（气）。</p><p>具体的生产方案，见3.2节，此处仅作数学讨论。</p><p><img src="/endfield-skydoc/logistics/src/assets/diagrams/flow-4d55ed00ef23efbb.q90-401539128a7401bb.webp" alt="流程图（源块 XU0rAD0t41nCGvQD2UE8yG）"></p><blockquote><p>此图由源文档流程图块导出；若本地未提供截图，请回到源文档查看交互版本。</p></blockquote><p><span id="source-block-u8XouKPIpUolO8tW4jkRhK"></span></p><h4 id="_4-4-多种原料多种成品的情形" tabindex="-1">4.4 多种原料多种成品的情形 <a class="header-anchor" href="#_4-4-多种原料多种成品的情形" aria-label="Permalink to &quot;4.4 多种原料多种成品的情形&quot;">​</a></h4><p><span id="source-block-sjN1ulZ3iQZXduIRPWdnao"></span></p><h4 id="_4-5-达到稳定前的暂态过程的时间估计-振荡周期计算" tabindex="-1">4.5 达到稳定前的暂态过程的时间估计，振荡周期计算 <a class="header-anchor" href="#_4-5-达到稳定前的暂态过程的时间估计-振荡周期计算" aria-label="Permalink to &quot;4.5 达到稳定前的暂态过程的时间估计，振荡周期计算&quot;">​</a></h4><p><a href="/endfield-skydoc/zh/4-6-equivalence-between-adaptive-operation-and-solving-linear-systems">4.6 自适应过程与线性方程组求解的等价性</a> · <a href="/endfield-skydoc/zh/ko-s-workshop">ko鸟的工作室</a></p><p><span id="source-block-X2BQguP94yFfFweLbHLcF1"></span></p><h2 id="零激活物浪费到更广泛的自适应" tabindex="-1">零激活物浪费到更广泛的自适应 <a class="header-anchor" href="#零激活物浪费到更广泛的自适应" aria-label="Permalink to &quot;零激活物浪费到更广泛的自适应&quot;">​</a></h2><blockquote><p>具体装置讲解已移动到：<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的自适应装置们</a></p></blockquote><p>“<strong>通过阻塞信号切换两种状态</strong>，而阻塞信号又受剩余库存量控制，由此形成反馈，最终的结果为稳定的震荡，生产与停工的时间比例<strong>自适应地调配出了所需的比例</strong>。”——kokobird</p><p><span id="source-block-mMMJhvpB2nsi8tOedocEpS"></span></p><h2 id="大周期反应震荡" tabindex="-1">大周期反应震荡 <a class="header-anchor" href="#大周期反应震荡" aria-label="Permalink to &quot;大周期反应震荡&quot;">​</a></h2><p>该课题基础前提二选一（可实现性：1&gt;2）：</p><p>1、工厂生产端对原料的适应区间覆盖两种状态的震荡。</p><p>2、可增加缓存来让机器在积累阶段消耗缓存，且机器过量输入不浪费。（存在击穿的风险）</p><p>我们存在有三种信号检测手段，分别为针对仓库存储的【满仓信号】、【空仓信号】，以及人为控制的【时钟信号】，由此，我们可两两组合以实现长周期震荡，保证仓库内始终存有原料，用以减少空仓配平课题导致的取货口数目增加，也用于减少直接满仓溢流而受取货波形影响造成的原产地无法存入的损耗。</p><p><span id="source-block-RbO6Tb93wuoHSR4UjEgOUb"></span></p><h3 id="满仓-时钟控制" tabindex="-1">满仓-时钟控制 <a class="header-anchor" href="#满仓-时钟控制" aria-label="Permalink to &quot;满仓-时钟控制&quot;">​</a></h3><p>其设计流程为：检测到仓储无法存入（满仓）→放行反应原料，增加消耗→信号存入时钟延时一段时间后，反应终止，开始积累。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-qGkAB86pF3OMhnOvn3sHBM"></span></p><h3 id="空仓-时钟控制" tabindex="-1">空仓-时钟控制 <a class="header-anchor" href="#空仓-时钟控制" aria-label="Permalink to &quot;空仓-时钟控制&quot;">​</a></h3><p>其设计流程为：检测到取货存在空缺（空仓）→阻塞反应原料，开始积累→信号存入时钟延时一段时间后，反应开启，增加消耗。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-xCX4qF1TzuYffAYgPKb9Pg"></span></p><h3 id="满仓-空仓控制" tabindex="-1">满仓-空仓控制 <a class="header-anchor" href="#满仓-空仓控制" aria-label="Permalink to &quot;满仓-空仓控制&quot;">​</a></h3><p>其设计流程为：检测到仓储无法存入（满仓）→放行反应原料，增加消耗→检测到取货存在空缺（空仓）→阻塞反应原料，开始积累。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-Bu1wyct41RhwxXeUeBGarA"></span></p><h3 id="时钟-时钟控制" tabindex="-1">时钟-时钟控制 <a class="header-anchor" href="#时钟-时钟控制" aria-label="Permalink to &quot;时钟-时钟控制&quot;">​</a></h3><p><s>我觉得这玩意很诡异兄弟，为什么不直接限速 30p/q unit/min呢.jpg</s></p><p>按照前文，我们可以在堵塞前后均增设时钟，此时等效调控积累阶段时长 T1 s，过耗阶段时长 T2 s，受控工厂消耗速率为v unit/min，T1与T2可调控时钟结构及内容物来更改，若是相同结构，在考虑传导信号迟延恒为 t s时，可以得到其消耗为 vT2/(T1+T2+t) unit/min，可以一定程度上实现p/q的限制消耗。</p><hr><p>以下是群主老大负责部分内容</p><p><span id="source-block-YZ6VeUpQiBgrSopI5kB9Ua"></span></p><h2 id="数字电路控制系统" tabindex="-1">数字电路控制系统 <a class="header-anchor" href="#数字电路控制系统" aria-label="Permalink to &quot;数字电路控制系统&quot;">​</a></h2><p><span id="source-block-EnP43uHPu7gRUdMRKQOpSk"></span></p><h3 id="周期点信号的生成" tabindex="-1">周期点信号的生成 <a class="header-anchor" href="#周期点信号的生成" aria-label="Permalink to &quot;周期点信号的生成&quot;">​</a></h3><p>如图所示，利用<a href="/endfield-skydoc/zh/basic-factory-principles#source-block-7R9931VccE38fQGWecdJ9R">基础基建原理</a>，可以做到每100秒输出一个蓝铁矿。</p><p>定义一种下游流通的物流，称为点信号物流，在这种物流稳定后，下游的每个物品的输出间隔都为尽可能大的固定时间间隔T的倍数，其中T相当大。显然，上面给出的蓝铁矿物流线是一个点信号物流，其T取100s，称T为该点信号物流的时钟周期，1/T为该点信号的时钟频率f，即10mHz。</p><p><span id="source-block-z2Za4dfyLVXsRqMMoPrgK3"></span></p><h3 id="时钟采样" tabindex="-1">时钟采样 <a class="header-anchor" href="#时钟采样" aria-label="Permalink to &quot;时钟采样&quot;">​</a></h3><p>反馈的要求是，将反馈源的流量状态转化为表示状态的数字信号0和1，其中0代表反馈源无效，1代表反馈源有效，容易想到，如果能够将反馈源的输出进行一定的整流，将其在一定时钟周期内的输出集中在周期内的同一段，例如：</p><p>1010101010——&gt;1110011000</p><p>利用<a href="/endfield-skydoc/zh/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">物流原理与一些名词</a>的结果，可以构造如图的装置，来达到上面的需求。</p><p>就可以通过对于时钟周期内某一个点进行采样来比较反馈源在一段时间内的输出总量与某个设定值的大小，如果更大，则采样为1，反之则采样为0。这个设定值的选取由采样点在单个时钟周期中的位置决定。</p><p>这个采样装置很好搭建，如图所示：</p><p><span id="source-block-JuE8e1LcfMB49QplhfUWqT"></span></p><h3 id="信号放大" tabindex="-1">信号放大 <a class="header-anchor" href="#信号放大" aria-label="Permalink to &quot;信号放大&quot;">​</a></h3><p>我们有时需要复用点信号，利用两次取补可以复制流量，这种功能可以集成为如下的信号放大器，其中每个出口都能输出一个复制信号：</p><p><span id="source-block-HHuZkGBvhHGd7puOwrgATO"></span></p><h3 id="信号运算" tabindex="-1">信号运算 <a class="header-anchor" href="#信号运算" aria-label="Permalink to &quot;信号运算&quot;">​</a></h3><p>利用协议存储箱的优先级，可以对点信号进行逻辑运算，其规律与<a href="/endfield-skydoc/zh/basic-factory-principles#source-block-EHhBNcPi9z2GuxnXC3X587">基础基建原理</a>中的简单逻辑运算完全相同。这种逻辑运算中的1为点信号物流在单个时钟周期中有一个输出，0为点信号物流在单个时钟周期中没有输出。</p><p>需要额外注意的是，如果信号运算的最后一次非运算后没有与运算，就意味着产生的运算将会是一个几乎是满的补带，不符合点信号物流要求，需要额外与高电平信号做一次与。</p><p><span id="source-block-x3ZJ3xNYB6VgMGagCAaz3A"></span></p><h3 id="信号还原" tabindex="-1">信号还原 <a class="header-anchor" href="#信号还原" aria-label="Permalink to &quot;信号还原&quot;">​</a></h3><p>经过运算后，需要将运算结果转化为输出，这里运算结果的含义为，如果运算产生了输出信号，则下游在本周期则不会持续输出反应原料。可以构造如图所示的装置来完成这一功能：</p><p>其中运算产生的输出信号蓝铁矿进入协议箱后，协议箱被阻塞，电池无法经过协议箱输出，其补带在延时一个周期时间后抵达协议箱出口，如果此时运算产生的输出信号停止，蓝铁输出，协议箱阻塞解除，在下个周期电池将持续输出。反之则蓝铁同时输入输出，蓝铁在协议箱中依然保有一个，协议箱阻塞保持，电池无法被输出。</p><p><span id="source-block-fc6GxHsFbpcKbKS9i9cPX6"></span></p><h3 id="利用延时器来改善性能" tabindex="-1">利用延时器来改善性能 <a class="header-anchor" href="#利用延时器来改善性能" aria-label="Permalink to &quot;利用延时器来改善性能&quot;">​</a></h3><p><a href="/endfield-skydoc/zh/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">物流原理与一些名词</a>中提到的滤波器消耗反应元件数和空间数极大，对于实际运用并不友好，而信号还原也要求延时一个周期时间，需要拉很长的传送带。可以通过一个内部流通的限流器来达到延时的作用，比如这就是一个100s的延时器：</p><p>利用这个延时器，可以简化信号还原的延时步骤，也就是说，能够依靠一个周期为2T的高电平点信号和一个延时为T的信号还原器来构造一个周期为2T的标准方波信号。依靠这个方波信号，可以将采样器的滤波装置简化如下，大大减少了占地和元件数：</p></div>',1)])])}const u=e(n,[["render",i]]);export{f as __pageData,u as default};
